css:
@page {
    size: A4 landscape;
    margin: 0;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  font-family: Arial, Helvetica, sans-serif;
  color: #000033;
}

.print-format {
  margin-left: 0 !important;
  margin-right: 0 !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  padding: 0 !important;
  width: 297mm !important;
  min-height: 210mm !important;
  orientation: Landscape;
  page-size: A4;
}



.print-format td {
    padding: 5px !important;
}

.print-format .meta-label,
.print-format .meta-value {
    padding: 0 !important;   
    padding-top: 5px !important;
}

@media screen {
  .print-format {
    width: 297mm !important;
    max-width: 297mm !important;
    min-height: 210mm !important;
  }
}

@media print {
  .print-format {
    width: 297mm !important;
    min-height: 210mm !important;
  }
}

.voucher-sheet {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.print-format .voucher-copy {
  width: 33.33%;
  vertical-align: top;
  padding: 0 !important;
  background: #fffdda;
  border-right: 1px dashed #8c8c8c;
}

.voucher-copy:last-child {
  border-right: 0;
}

.copy-inner {
  min-height: 210mm;
  padding: 10px 10px 12px;
  box-sizing: border-box;
  position: relative;
}

.copy-title {
  text-align: right;
  font-size: 11px;
  line-height: 1;
  margin: 0 -5px 3px 0;
  color: #000033;
}

.serial-row,
.brand-row,
.bank-table,
.meta-table,
.amount-table,
.words-row,
.sign-table,
.sign-inner {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.serial-row {
  margin-bottom: 4px;
}

.serial-row td {
  font-size: 10px;
  color: #000033;
  padding: 0;
  vertical-align: bottom;
}

.print-format td.serial-label {
  width: 52%;
  text-align: right;
  padding: 0 !important;
  padding-right: 5px !important;
  white-space: nowrap;
}

.print-format td.serial-value {
  width: 64%;
  text-align: center;
  border-bottom: 1px solid #4e4e4e;
  font-size: 12px;
  padding: 0 !important;
}

.brand-row {
  margin-bottom: 8px;
}

.brand-row td {
  padding: 0;
  vertical-align: middle;
}

.print-format .brand-logo-cell {
  width: 80px;
  padding: 0 !important;
}

.brand-logo {
    width: 80px;
    height: auto;
    display: block;
}

.brand-name {
  color: #f11b21;
  font-size: 22px;
  font-weight: 600;
  line-height: 1.02;
  white-space: nowrap;
  margin-top: 19px;
}

.bank-table td,
.bank-note,
.amount-table th,
.amount-table td {
  border: 1px solid #4f4f4f;
}

.bank-table {
  margin-bottom: 0;
}

.bank-table td {
  width: 50%;
  padding: 6px 4px 5px;
  text-align: center;
  color: #000033;
  font-size: 12px;
  line-height: 1.12;
}

.bank-table strong {
  display: block;
  font-size: 13px;
  line-height: 1.1;
  margin-bottom: 3px;
}

.bank-note {
  border-top: 0;
  text-align: center;
  color: #000033;
  font-size: 11px;
  line-height: 1.1;
  padding: 5px 8px 4px;
  margin-bottom: 10px;
}

.meta-table td {
  padding: 5px 0 3px;
  font-size: 10px;
  color: #000033;
  vertical-align: bottom;
}

.meta-label {
  width: 30%;
  padding-right: 8px !important;
  white-space: nowrap;
}

.meta-value {
  width: 70%;
  border-bottom: 1px solid #6d6d6d;
  padding-left: 1px !important;
}

.amount-table {
  margin-top: 10px;
}

.amount-table th,
.amount-table td {
  color: #000033;
  font-size: 10px;
  padding: 3px !important;
}

.amount-table th {
  text-align: center;
  font-weight: 700;
  padding-top: 2px;
  padding-bottom: 2px;
  line-height: 1;
}

.amount-table td:last-child,
.amount-table th:last-child {
  width: 28%;
  text-align: center;
}

.grand-label {
  text-align: right;
}

.grand-value {
  text-align: center;
}

.words-row {
  margin-top: 10px;
  margin-bottom: 10px !important;
}

.words-row td {
  padding: 0 !important;
  vertical-align: bottom;
  font-size: 10px;
  color: #000033
}

.words-label {
  width: 30%;
  white-space: nowrap;
  padding-right: 8px !important;
}

.words-value {
  width: 70%;
  border-bottom: 1px solid #6d6d6d;
  padding-left: 1px !important;
}

.terms-title {
  margin-top: 2px;
  color: #000033;
  font-size: 11px;
  font-weight: 700;
}

.terms-list {
  margin: 5px 0 0 18px;
  padding-left: 18px;
  color: #000033;
  font-size: 9px;
  line-height: 1.2;
}

.terms-list li {
  margin: 0;
}

.sign-table {
    position: absolute;
    bottom: 20px;
    left: 0;
    right: 0;
}

.sign-table > tbody > tr > td {
  width: 50%;
  vertical-align: bottom;
  padding: 0 8px 0 0;
}

.sign-table > tbody > tr > td:last-child {
  padding-right: 0;
  padding-left: 12px;
}

.sign-label-cell {
  width: 42%;
  font-size: 10px;
  color: #000033;
  white-space: nowrap;
  vertical-align: bottom;
  padding: 0 6px 0 0;
}

.sign-line-cell {
  width: 58%;
  border-bottom: 1px solid #4f4f4f;
  height: 11px;
}


/* fee challan additions */
.amount-table tbody td:first-child {
  text-align: left;
  word-break: break-word;
}

.amount-table .ch {
  font-size: 8px;
  color: #4a4a6a;
  white-space: nowrap;
}

.amount-table .late-row td {
  font-size: 9px;
  background: #f7f2e2;
}

.amount-table .late-row .grand-label {
  line-height: 1.15;
}
